import{_ as t,o as r,c as e,a3 as l}from"./chunks/framework.BveOjhN0.js";const m=JSON.parse('{"title":"人工智能辅修过半总结","description":"人工智能辅修专业小学期过半的学习回顾，涵盖机器学习、计算机视觉与机器人控制三门课程的体验与感悟。","frontmatter":{"date":"2026-07-24T00:00:00.000Z","tags":["学习总结"],"description":"人工智能辅修专业小学期过半的学习回顾，涵盖机器学习、计算机视觉与机器人控制三门课程的体验与感悟。"},"headers":[],"relativePath":"posts/ai-minor-semester-summary.md","filePath":"posts/ai-minor-semester-summary.md"}'),o={name:"posts/ai-minor-semester-summary.md"};function i(s,a,n,p,h,u){return r(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="人工智能辅修过半总结" tabindex="-1">人工智能辅修过半总结 <a class="header-anchor" href="#人工智能辅修过半总结" aria-label="Permalink to &quot;人工智能辅修过半总结&quot;">​</a></h1><p>时光飞逝，小学期已经过半。这段时间里，我选择了辅修人工智能专业，开启了一段全新的学习旅程。在这里记录一下这段时间的学习经历，留给未来的自己看看。</p><h2 id="学习背景" tabindex="-1">学习背景 <a class="header-anchor" href="#学习背景" aria-label="Permalink to &quot;学习背景&quot;">​</a></h2><p>选择辅修AI，纯粹是因为对这个领域比较感兴趣。从AlphaGo到自动驾驶，AI技术正在改变着我们的世界，我也想深入了解其中的奥秘。</p><p>在开始AI辅修之前，我还学习了本学院的<strong>开源软件开发技术</strong>课程。</p><h2 id="已完成课程" tabindex="-1">已完成课程 <a class="header-anchor" href="#已完成课程" aria-label="Permalink to &quot;已完成课程&quot;">​</a></h2><h3 id="📚-机器学习方法" tabindex="-1">📚 机器学习方法 <a class="header-anchor" href="#📚-机器学习方法" aria-label="Permalink to &quot;📚 机器学习方法&quot;">​</a></h3><p>这门课让我第一次系统地接触了机器学习的核心概念。从监督学习到无监督学习，从线性回归到神经网络，每一个算法都让我感受到了数学的魅力。</p><p><strong>印象最深的点：</strong></p><ul><li>矩阵运算和线性代数在机器学习中无处不在，理解这些数学基础对掌握算法至关重要</li><li>各种优化算法如梯度下降，让我明白&quot;聪明的尝试&quot;比&quot;暴力搜索&quot;更有效率</li></ul><p><strong>学习挑战：</strong></p><ul><li>课件全是英文的，阅读起来需要花费更多时间和精力</li><li>一些数学推导比较复杂，需要反复琢磨才能理解</li><li>线性代数虽然期末考了满分，但时隔一学期几乎忘光了，导致矩阵运算相关的知识运用得不太好</li></ul><h3 id="🖼️-计算机视觉算法与应用" tabindex="-1">🖼️ 计算机视觉算法与应用 <a class="header-anchor" href="#🖼️-计算机视觉算法与应用" aria-label="Permalink to &quot;🖼️ 计算机视觉算法与应用&quot;">​</a></h3><p>作为图像处理方向的学习者，这门课让我受益匪浅。从图像预处理到特征提取，从目标检测到图像分类，每一个环节都充满了挑战和乐趣。</p><p><strong>印象最深的点：</strong></p><ul><li>卷积神经网络(CNN)的设计思想非常精妙，多层卷积能够自动提取图像特征</li><li>图像处理中的各种滤波器，让我对图像有了全新的认识</li></ul><p><strong>学习挑战：</strong></p><ul><li>同样是英文课件，专业术语较多，需要不断查阅资料</li><li>矩阵运算依然是重点和难点，很多算法都建立在矩阵变换的基础上</li></ul><h3 id="🤖-面向智能制造的小型机器人控制" tabindex="-1">🤖 面向智能制造的小型机器人控制 <a class="header-anchor" href="#🤖-面向智能制造的小型机器人控制" aria-label="Permalink to &quot;🤖 面向智能制造的小型机器人控制&quot;">​</a></h3><p>这门课相对来说比较轻松有趣，也是我最喜欢的一门课。我们亲手操作了机器人，编写了控制程序。</p><p><strong>做过的项目：</strong></p><ul><li>完成了简单的闪灯控制实验</li><li>控制手臂机器人完成抓取和放置任务</li><li>控制并联机器人进行轨迹规划</li></ul><p><strong>学习感受：</strong></p><ul><li>相比于纯理论课程，动手实践让我更有成就感</li><li>看到自己写的代码让机器人动起来，那种感觉非常棒</li></ul><h2 id="学习感悟" tabindex="-1">学习感悟 <a class="header-anchor" href="#学习感悟" aria-label="Permalink to &quot;学习感悟&quot;">​</a></h2><p>这段时间的学习让我有很多感悟：</p><ol><li><p><strong>数学是AI的基石</strong>：无论是机器学习还是计算机视觉，矩阵运算、线性代数都是绕不开的基础。扎实的数学功底能够让我们更好地理解算法原理。</p></li><li><p><strong>英文能力很重要</strong>：很多优质的教材和论文都是英文的，提高英文阅读能力对学习AI非常有帮助。</p></li><li><p><strong>实践出真知</strong>：理论学习很重要，但动手实践能够加深理解。机器人控制课让我体会到了实践的乐趣。</p></li></ol><h2 id="未来期待" tabindex="-1">未来期待 <a class="header-anchor" href="#未来期待" aria-label="Permalink to &quot;未来期待&quot;">​</a></h2><p>接下来的两周，还有<strong>人工智能与Python编程</strong>和<strong>人工智能引领实训</strong>两门课程。具体会学到什么还充满未知，但我已经迫不及待，希望能在剩下的小学期时光里继续收获知识与快乐，享受这段AI学习之旅。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>小学期过半，收获满满。虽然学习过程中遇到了一些挑战，但每一次克服困难后的成就感都是无与伦比的。</p><p>感谢这段时间的学习经历，也期待接下来的课程能够带来更多惊喜。未来的路还很长，继续加油！</p>',32)])])}const c=t(o,[["render",i]]);export{m as __pageData,c as default};
